	\centering
	\includegraphics[width=\textwidth]{cropNzoom.png}
    \caption{Image preprocessing steps with a) the original image, b) the cropped image based on object detection and c) the quarter image. Zero padding was used to ensure a consistent resolution with a centred pillar.}
    \label{fig:resOpti}
